#!/usr/bin/env python3
"""Adapt the pinned WebKit UA definitions; never used by builds or at runtime."""
import json
import re
from pathlib import Path

root = Path(__file__).resolve().parent
source = re.sub(r'/\*.*?\*/', '', (root / 'counterStyles.css').read_text(), flags=re.S)
styles = {
    name: dict(re.findall(r'([\w-]+)\s*:\s*([^;]+);', body))
    for name, body in re.findall(r'@counter-style\s+([\w-]+)\s*\{([^}]*)\}', source)
}


def tokens(value):
    # The pinned input only uses CSS strings, idents and integer descriptors.
    pattern = r'''"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|(?:\\[0-9a-fA-F]{1,6}\s?|[^\s,])+'''
    def decode(token):
        if token[0] in "\"'":
            token = token[1:-1]
        return re.sub(r'\\([0-9a-fA-F]{1,6})\s?|\\(.)',
                      lambda match: chr(int(match[1], 16)) if match[1] else match[2], token)
    return [decode(token) for token in re.findall(pattern, value)]


def resolve(name):
    own = styles[name].copy()
    system = own['system'].split()
    if system[0] == 'extends':
        parent = resolve(system[1])
        own.pop('system')
        return parent | own
    return own


def quoted(value):
    return json.dumps(value, ensure_ascii=False)


def variant(name):
    return 'LeadingZero' if name == 'decimal-leading-zero' else ''.join(word.title() for word in name.split('-'))


complex_systems = {
    'simplified-chinese-informal': 'SimplifiedInformal', 'simplified-chinese-formal': 'SimplifiedFormal',
    'traditional-chinese-informal': 'TraditionalInformal', 'traditional-chinese-formal': 'TraditionalFormal',
    'japanese-informal': 'JapaneseInformal', 'japanese-formal': 'JapaneseFormal',
    'korean-hangul-formal': 'KoreanHangul', 'korean-hanja-informal': 'KoreanInformal',
    'korean-hanja-formal': 'KoreanFormal',
}
rows = []
for name in styles:
    rule = resolve(name)
    kind = rule['system'].removeprefix('-internal-')
    if kind in complex_systems:
        system = f'System::Cjk(complex::Cjk::{complex_systems[kind]})'
    else:
        system = 'System::' + ''.join(word.title() for word in kind.split('-'))
    symbols = '[' + ', '.join(quoted(symbol) for symbol in tokens(rule.get('symbols', ''))) + ']'
    additive = '[' + ', '.join(
        f'({int(weight)}, {quoted(symbol)})'
        for weight, symbol in (tokens(pair) for pair in rule.get('additive-symbols', '').split(',') if pair.strip())
    ) + ']'
    default_range = '1 infinite' if kind in ('alphabetic', 'symbolic', 'ethiopic-numeric') else '-infinite infinite'
    if kind == 'fixed':
        default_range = f'1 {len(tokens(rule["symbols"]))}'
    low, high = tokens(rule.get('range', default_range))
    low = 'i64::MIN' if low == '-infinite' else low
    high = 'i64::MAX' if high == 'infinite' else high
    negative = tokens(rule.get('negative', "'-'"))
    assert len(negative) == 1, name
    suffix = tokens(rule.get('suffix', "'. '"))
    assert len(suffix) == 1 and 'prefix' not in rule, name
    padding = tokens(rule.get('pad', "0 ''"))
    fallback = str(rule.get('fallback') == 'cjk-decimal').lower()
    assert rule.get('fallback', 'decimal') in ('decimal', 'cjk-decimal'), name
    definition = (f'Definition {{ system: {system}, symbols: &{symbols}, additive: &{additive}, '
                  f'range: ({low}, {high}), negative: {quoted(negative[0])}, suffix: {quoted(suffix[0])}, '
                  f'pad: ({int(padding[0])}, {quoted(padding[1])}), fallback_cjk: {fallback} }}')
    rows.append(f'    {variant(name)} => ({quoted(name)}, {definition}),')

destination = root.parents[1] / 'crates/app-core/src/preview/rich/lists/data.rs'
destination.parent.mkdir(exist_ok=True)
destination.write_text(
    '// Generated by vendor/css-counter-styles/generate.py; do not edit.\n'
    '// Adapted from WebKit (C) 2023 Apple Inc., BSD-2-Clause.\n'
    '// Provenance and complete license: vendor/css-counter-styles/UPSTREAM.md.\n'
    'predefined! {\n' + '\n'.join(rows) + '\n}\n')
